-- Execute no SQL Editor de um projeto Supabase novo.
create extension if not exists pgcrypto;
create table public.companies (id uuid primary key default gen_random_uuid(), name text not null check (length(trim(name))>1), created_at timestamptz not null default now());
create table public.memberships (company_id uuid not null references public.companies(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('owner','manager','member')), primary key(company_id,user_id));
create table public.units (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, name text not null, unique(id,company_id));
create table public.templates (id uuid primary key default gen_random_uuid(), company_id uuid references public.companies(id) on delete cascade, cadence text not null check(cadence in ('daily','weekly','monthly')), name text not null, created_at timestamptz not null default now(), unique(id,company_id));
create table public.sections (id uuid primary key default gen_random_uuid(), template_id uuid not null references public.templates(id) on delete cascade, title text not null, position integer not null);
create table public.items (id uuid primary key default gen_random_uuid(), section_id uuid not null references public.sections(id) on delete cascade, title text not null, position integer not null);
create table public.entries (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, unit_id uuid not null, template_id uuid not null references public.templates(id), author_id uuid not null references auth.users(id), period_start date not null, status text not null default 'draft' check(status in ('draft','submitted')), details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id,unit_id,template_id,author_id,period_start), foreign key(unit_id,company_id) references public.units(id,company_id));
create table public.entry_answers (entry_id uuid not null references public.entries(id) on delete cascade, item_id uuid not null references public.items(id), done boolean not null default false, primary key(entry_id,item_id));
create index on public.entries(company_id,period_start desc);
create index on public.memberships(user_id);
create or replace function public.is_member(cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.memberships m where m.company_id=cid and m.user_id=(select auth.uid())) $$;
create or replace function public.is_admin(cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.memberships m where m.company_id=cid and m.user_id=(select auth.uid()) and m.role in ('owner','manager')) $$;
create or replace function public.entry_company(eid uuid) returns uuid language sql stable security definer set search_path=public as $$ select company_id from public.entries where id=eid $$;
create or replace function public.entry_is_editable(eid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.entries where id=eid and status='draft' and author_id=auth.uid()) $$;
create or replace function public.can_read_template(tid uuid,cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.templates where id=tid and (company_id is null or company_id=cid)) $$;
create or replace function public.new_company(company_name text,unit_name text default 'Unidade principal') returns uuid language plpgsql security definer set search_path=public as $$ declare cid uuid;begin if auth.uid() is null then raise exception 'Autenticação necessária'; end if; if length(trim(company_name))<2 then raise exception 'Informe o nome da empresa';end if; insert into public.companies(name) values(trim(company_name)) returning id into cid;insert into public.memberships(company_id,user_id,role) values(cid,auth.uid(),'owner');insert into public.units(company_id,name) values(cid,coalesce(nullif(trim(unit_name),''),'Unidade principal'));return cid;end $$;
revoke all on function public.new_company(text,text) from public;grant execute on function public.new_company(text,text) to authenticated;
create or replace function public.set_entry_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end $$;
create trigger entries_updated before update on public.entries for each row execute function public.set_entry_updated_at();
create or replace function public.validate_entry() returns trigger language plpgsql security definer set search_path=public as $$ begin if not public.can_read_template(new.template_id,new.company_id) then raise exception 'Modelo não pertence à empresa';end if; if tg_op='UPDATE' then if old.status='submitted' then raise exception 'Registro finalizado não pode ser alterado'; end if; if (new.company_id,new.unit_id,new.template_id,new.author_id,new.period_start) is distinct from (old.company_id,old.unit_id,old.template_id,old.author_id,old.period_start) then raise exception 'Identificadores do registro são imutáveis';end if; end if;return new;end $$;
create trigger validate_entries before insert or update on public.entries for each row execute function public.validate_entry();
create or replace function public.validate_answer() returns trigger language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from public.items i join public.sections s on s.id=i.section_id join public.entries e on e.template_id=s.template_id where i.id=new.item_id and e.id=new.entry_id) then raise exception 'Item não corresponde ao modelo do registro';end if;return new;end $$;
create trigger validate_answers before insert or update on public.entry_answers for each row execute function public.validate_answer();
alter table public.companies enable row level security;
alter table public.memberships enable row level security;
alter table public.units enable row level security;
alter table public.templates enable row level security;
alter table public.sections enable row level security;
alter table public.items enable row level security;
alter table public.entries enable row level security;
alter table public.entry_answers enable row level security;
create policy companies_select on public.companies for select to authenticated using(public.is_member(id));
create policy memberships_select on public.memberships for select to authenticated using(public.is_member(company_id));
create policy units_select on public.units for select to authenticated using(public.is_member(company_id));
create policy units_insert on public.units for insert to authenticated with check(public.is_admin(company_id));
create policy templates_select on public.templates for select to authenticated using(company_id is null or public.is_member(company_id));
create policy sections_select on public.sections for select to authenticated using(exists(select 1 from public.templates t where t.id=template_id and (t.company_id is null or public.is_member(t.company_id))));
create policy items_select on public.items for select to authenticated using(exists(select 1 from public.sections s join public.templates t on t.id=s.template_id where s.id=section_id and (t.company_id is null or public.is_member(t.company_id))));
create policy entries_select on public.entries for select to authenticated using(public.is_member(company_id));
create policy entries_insert on public.entries for insert to authenticated with check(public.is_member(company_id) and author_id=auth.uid() and public.can_read_template(template_id,company_id));
create policy entries_update on public.entries for update to authenticated using(public.is_member(company_id) and author_id=auth.uid() and status='draft') with check(public.is_member(company_id) and author_id=auth.uid());
create policy answers_select on public.entry_answers for select to authenticated using(public.is_member(public.entry_company(entry_id)));
create policy answers_insert on public.entry_answers for insert to authenticated with check(public.entry_is_editable(entry_id));
create policy answers_update on public.entry_answers for update to authenticated using(public.entry_is_editable(entry_id)) with check(public.entry_is_editable(entry_id));
-- Inserção das respostas antes de finalizar o registro. Membros não podem alterar registros de outra empresa.
